  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Le chlorhydrate d’hydroquinidine NE DOIT JAMAIS ÊTRE UTILISÉ dans les situations suivantes :', 'hypersensibilité à l’hydroquinidine ou à la quinidine (voir rubrique 4.4) ou à l’un des excipients mentionnés à la rubrique 6.1,', 'bloc auriculo-ventriculaire non appareillé,', 'bloc de branche complet, autres troubles marqués de la conduction intraventriculaire,', 'troubles de l’automatisme sinusal (maladie de l’oreillette) non appareillés,', 'troubles du rythme de l’intoxication digitalique,', 'torsades de pointes,', 'QT long,', 'insuffisance cardiaque,', 'association avec les médicaments torsadogènes (sauf antiparasitaires, neuroleptiques et méthadone) :', 'o les antiarythmiques de classe Ia (quinidine, disopyramide),', 'o les antiarythmiques de classe III (amiodarone, sotalol, dofétilide, ibutilide),']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'L’incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.', 'Comme pour les autres antiarythmiques de classe I, il n’existe pas d’essai contrôlé mettant en évidence un effet bénéfique de l’hydroquinidine en termes de survie ou de mort subite.', 'Hypersensibilité/idiosyncrasie', 'L’éventualité d’accidents gravissimes en cas d’hypersensibilité (en particulier arrêt cardiocirculatoire inopiné) conduit à tester la sensibilité des patients avant la mise en route d’un traitement par l’hydroquinidine :', 'une gélule test est administrée,', 'par contre, si les modifications électrocardiographiques ne se produisent qu’après 48 heures (et en l’absence des autres signes décrits ci-dessus), il suffira de diminuer les doses,', 'la survenue d’une fièvre inexpliquée doit conduire à la réalisation d’un bilan hépatique.', 'Le chlorhydrate d’hydroquinidine EST GÉNÉRALEMENT DÉCONSEILLÉ dans les situations suivantes :', 'grossesse, allaitement,', 'myasthénie,', 'Ce médicament contient du saccharose.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments antiarythmiques', 'De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l’ECG.', 'L’association d’antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L’association d’antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d’effets indésirables cardiaques.', 'Médicaments susceptibles de donner des torsades de pointes', 'Ce trouble du rythme cardiaque grave peut être provoqué par un certain nombre de médicaments, antiarythmiques ou non.', 'L''hypokaliémie (cf. médicaments hypokaliémiants) est un facteur favorisant, de même que la bradycardie (cf. médicaments bradycardisants) ou un allongement préexistant de l''intervalle QT, congénital ou acquis.', 'Les médicaments à l’origine de cet effet indésirable sont notamment les antiarythmiques de classe Ia et III, et certains neuroleptiques.', 'D''autres molécules n’appartenant pas à ces classes sont également en cause.', 'Pour le dolasétron, l’érythromycine, la spiramycine et la vincamine, seules les formes administrées par voie intraveineuse sont concernées par cette interaction.', 'L''utilisation d''un médicament torsadogène avec un autre médicament torsadogène est contre-indiquée en règle générale.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Classification des effets indésirables selon la convention suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100,', 'Très Fréquent', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.', 'la survenue d’une fièvre inexpliquée doit conduire à la réalisation d’un bilan hépatique.']);
