  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTIARYTHMIQUE - Classe Ia, code ATC : C01BA03: système cardiovasculaire.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Le disopyramide NE DOIT JAMAIS ETRE UTILISE dans les cas suivants :', 'hypersensibilité au disopyramide ;', 'infarctus du myocarde (aigu ou ancien) sauf en cas de tachycardie ventriculaire menaçant le pronostic vital ;', 'insuffisance cardiaque, quel que soit le trouble rythmique ;', 'bloc de branche gauche complet, bloc bifasciculaire, bloc auriculoventriculaire du 2e et du 3e degré, dysfonctionnement sinusal et maladie de l''oreillette, en l''absence d''appareillage ;', 'allongement de QT préexistant ;', 'glaucome, myasthénie, troubles uréthroprostatiques, notamment hypertrophie prostatique (liés à l''activité anticholinergique du disopyramide).', 'association avec les médicaments donnant des torsades de pointes :', 'o les antiarythmiques de classe Ia (hydroquinidine, quinidine),', 'o les antiarythmiques de classe III (amiodarone, sotalol, dofétilide, ibutilide),', 'o le sultopride (neuroleptique),', 'o et autres médicaments tels que: bépridil, cisapride, diphémanil, érythromycine IV, mizolastine, vincamine IV...']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.', 'Comme pour les autres antiarythmiques de classe I, il n''existe pas d''essai contrôlé mettant en évidence un effet bénéfique du disopyramide en termes de survie ou de mort subite.', 'En raison de la présence de saccharose, ce médicament est contre-indiqué en cas d''intolérance au fructose, de syndrome de malabsorption du glucose et du galactose ou de déficit en sucrase-isomaltase.', 'Précautions d''emploi', 'Effets pro-arythmiques', 'Le disopyramide, comme d''autres agents anti-arythmiques, peut provoquer la survenue d''une forme plus sévère d''arythmie, augmenter la fréquence d''une arythmie préexistante ou aggraver la sévérité des symptômes.', 'Une variation spontanée du trouble du rythme propre au patient peut se révéler difficile à distinguer d''une aggravation secondaire à l''administration du médicament.', 'L''apparition d''extrasystoles ventriculaires plus nombreuses ou polymorphes doit faire interrompre le traitement.', 'Antécédents d''insuffisance cardiaque', 'Modifications électrocardiographiques', 'Le disopyramide doit être administré avec précaution chez les patients ayant des anomalies préexistantes de conduction.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Risque majoré de troubles ventriculaires, notamment de torsades de pointes.', '+ Bêta-bloquants dans l''insuffisance cardiaque (bisoprolol, carvédilol, métoprolol)', 'Effet inotrope négatif avec risque de décompensation cardiaque (synergie des effets).', 'Associations déconseillées', '+ Erythromycine (voie orale), clarithromycine, josamycine', 'Risque de majoration des effets indésirables du disopyramide: hypoglycémies sévères, allongement de l''intervalle QT et troubles du rythme ventriculaire graves, notamment à type de torsade de pointes.', '+ Certains neuroleptiques (thioridazine, chlorpromazine, lévomépromazine, trifluopérazine, cyamémazine, sulpiride, amisulpride, tiapride, halopéridol, pimozide, dropéridol...)', 'Risque majoré de troubles du rythme ventriculaire, notamment de torsades de pointes.', '+ Halofantrine, pentamidine, moxifloxacine', 'Si cela est possible, interrompre le médicament torsadogène non anti-infectieux.', 'Si l''association ne peut être évitée, contrôle préalable du QT et surveillance électrocardiographique monitorée.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Comme tous les antiarythmiques, le disopyramide peut entraîner l''aggravation ou l''apparition de troubles du rythme ventriculaire (tachycardie ventriculaire, fibrillation ventriculaire, torsades de poi', 'Le disopyramide augmente l''intervalle QT et peut être responsable de torsades de pointes.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L''incidence de la mortalité et des arrêts cardiaques non mortels sous ces médicaments a été supérieure à celle observée dans le groupe contrôle sous placebo.']);
  -- flecainide (CIS 61264178, scored)
  m := pg_temp.jp_matrice_by_norm('flecainide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTI-ARYTHMIQUE, CLASSE IC, code ATC : C01BC04');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT PAS ETRE UTILISE dans les cas suivants :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'infarctus du myocarde (aigu ou ancien) sauf en cas de tachycardie ventriculaire menaçant le pronostic vital,', 'insuffisance cardiaque, quel que soit le trouble rythmique,', 'bloc de branche gauche complet, bloc bifasciculaire, bloc auriculo-ventriculaire du 2ème et du 3ème degré, dysfonctionnement sinusal et maladie de l''oreillette, en l''absence d''appareillage,', 'choc cardiogénique,', 'syndrome de Brugada connu.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L''incidence de la mortalité et des arrêts cardiaques non mortels sous flécaïnide a été supérieure à celle observée dans le groupe sous contrôle placebo.', 'Comme pour les autres antiarythmiques de classe I, il n''existe pas d''essai contrôlé mettant en évidence un effet bénéfique de l''acétate de flécaïnide en termes de survie ou de mort subite.', 'Le traitement par flécaïnide doit être initié par un médecin ayant la compétence de la prise en charge des patients atteints de cardiopathies.', 'Toute instauration ou changement dans la prescription nécessite en effet une surveillance clinique et électrocardiographique permettant d’évaluer l’effet du traitement.', 'Lors du changement d’un médicament contenant du flécaïnide à un autre, il est recommandé pour les patients à risque d’effectuer une surveillance étroite.', 'Précautions particulières d''emploi', 'Effets pro-arythmiques', 'Une variation spontanée du trouble du rythme propre au patient peut se révéler difficile à distinguer d''une aggravation secondaire à l''administration du médicament.', 'L''apparition d''extrasystoles ventriculaires plus nombreuses ou polymorphes doit faire interrompre le traitement.', 'Antécédents d''insuffisance cardiaque', 'Modifications électrocardiographiques']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle ECG.', 'L’association d’antiarythmiques de même classe est déconseillée sauf cas exceptionnels en raison du risque accru d’effets indésirables cardiaques.', 'Associations déconseillées', '+ Anti-arythmiques de classe I (quinidine, hydroquinidine, disopyramide, mexilétine, lidocaïne, propafénone, cibenzoline)', 'L''acétate de flécaïnide ne doit pas être associé avec les autres anti-arythmiques de la classe I, sauf cas exceptionnels, en raison du risque accru d''effets cardiaques indésirables.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10)', 'Fréquent (≥ 1/100,', 'Peu fréquent (≥ 1/1.000,', 'Rare (≥ 1/10.000,', 'Peu fréquent : diminution du nombre de globules rouges, diminution du nombre de globules blancs et diminution du nombre de plaquettes.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L''incidence de la mortalité et des arrêts cardiaques non mortels sous flécaïnide a été supérieure à celle observée dans le groupe sous contrôle placebo.', 'Toute instauration ou changement dans la prescription nécessite en effet une surveillance clinique et électrocardiographique permettant d’évaluer l’effet du traitement.', 'Lors du changement d’un médicament contenant du flécaïnide à un autre, il est recommandé pour les patients à risque d’effectuer une surveillance étroite.']);
  -- propafenone (CIS 66843923, scored)
  m := pg_temp.jp_matrice_by_norm('propafenone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Antiarythmique, code ATC : C01BC03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Il convient d''initier le traitement avec des posologies faibles et de pratiquer des contrôles ECG.', 'Prévention des récidives des tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie et en l''absence d''altération de la fonction ventriculaire gauche.', 'Prévention des chocs cardiaques électriques chez certains patients porteurs de défibrillateurs implantables.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT JAMAIS être utilisé dans les cas suivants :', 'hypersensibilité connue au chlorhydrate de propafénone ou à l''un des excipients,', 'syndrome de Brugada connu (voir rubrique 4.4),', 'antécédent d’infarctus du myocarde au cours des 3 mois précédents,', 'insuffisance cardiaque congestive non contrôlée avec débit ventriculaire gauche inférieur à 35%,', 'choc cardiogénique, sauf si celui-ci est provoqué par l’arythmie,', 'bradycardie symptomatique sévère,', 'bloc de branche ou bloc distal en l’absence de stimulateur cardiaque, blocs auriculo-ventriculaires du 2ème et du 3ème degré, dysfonctionnement sinusal, anomalies de la conduction auriculaire,', 'hypotension sévère,', 'cirrhose,', 'hypokaliémie, hyperkaliémie ou hypomagnésémie (voir rubrique 4.4),', 'bronchopneumopathie obstructive sévère,']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['La propafénone comme les autres antiarythmiques peut provoquer des effets proarythmiques i.e. elle peut provoquer de nouvelles arythmies ou aggraver des arythmies préexistantes (voir rubrique 4.8).', 'Comme pour les autres antiarythmiques de classe Ic, les sujets atteints d''anomalies cardiaques structurelles significatives peuvent être prédisposés à des effets indésirables sévères.', 'La propafénone est donc contre‑indiquée chez ces patients (voir rubrique 4.3).', 'L’exposition à la propafénone chez les porteurs asymptomatiques du syndrome de Brugada peut révéler le syndrome ou entraîner des modifications sur l’ECG semblables à celles induites par un syndrome de Brugada.', 'Après l’initiation du traitement par la propafénone, tout symptôme suggérant un syndrome de Brugada doit imposer la réalisation d’un ECG (voir rubrique 4.3).', 'Effets pro-arythmiques :', 'La propafénone, comme d''autres agents anti-arythmiques, peut provoquer la survenue d''une forme plus sévère d''arythmie, augmenter la fréquence d''une arythmie préexistante ou aggraver la sévérité des symptômes.', 'Une variation spontanée du trouble du rythme propre au patient peut se révéler difficile à distinguer d''une aggravation secondaire à l''administration du médicament.', 'L''apparition d''extrasystoles ventriculaires plus nombreuses ou polymorphes doit faire interrompre le traitement.', 'Modifications électrocardiographiques :', 'La propafénone doit être administrée avec précaution chez les patients ayant des anomalies préexistantes de conduction.', 'La survenue sous traitement d''un bloc auriculo-ventriculaire, d''un bloc de branche complet permanent ou d''un bloc sino-auriculaire doit faire interrompre la propafénone.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l''ECG.', 'L’association d’antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée', 'L’association d’antiarythmiques de même classe est déconseillée, sauf cas exceptionnels, en raison du risque accru d’effets indésirables cardiaques.', 'Une surveillance clinique étroite et une adaptation de la posologie sont nécessaires lors de l’administration concomitante de propafénone avec des inhibiteurs de ces enzymes.', 'Il n''a pas été noté d''effet significatif sur la pharmacocinétique de la propafénone et de la lidocaïne lors de leur administration concomitante.', 'Cependant, il a été rapporté que l''association de propafénone et de lidocaïne augmente le risque d''effets indésirables neurologiques centraux de la lidocaïne.', 'Une augmentation des concentrations plasmatiques de propafénone peut se produire lorsque celle-ci est associée aux inhibiteurs sélectifs de la recapture de la sérotonine (ISRS) comme la fluoxétine et la paroxétine.', 'La co-administration de propafénone et de fluoxétine chez des métaboliseurs rapides a augmenté la Cmax et l''ASC de la propafénone S de respectivement 39 et 50%, celles de la propafénone R de 71 et 50%.', 'Une posologie plus faible de propafénone peut être suffisante pour obtenir l''effet thérapeutique souhaité.', 'L’administration concomitante de propafénone et de médicaments inducteurs du CYP3A4 (phénobarbital, rifampicine) peut diminuer les concentrations plasmatiques de propafénone et donc son efficacité antiarythmique.', 'La réponse à un traitement par la propafénone doit être surveillée lors de traitement concomitant chronique par le phénobarbital et/ou la rifampicine.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquents et très fréquents associés au traitement par la propafénone sont des étourdissements, des troubles de la conduction cardiaque et des palpitations.', 'Très fréquent ≥ 1/10', 'Fréquent ≥ 1/100,', 'Peu fréquent ≥ 1/100,', 'Agranulocytose, leucopénie, granulopénie']);
  -- amiodarone (CIS 64408662, scored)
  m := pg_temp.jp_matrice_by_norm('amiodarone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTIARYTHMIQUE CLASSE III, code ATC : C01BD01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention des récidives des :', 'tachycardies ventriculaires menaçant le pronostic vital: le traitement doit être instauré en milieu hospitalier sous monitorage;', 'tachycardies ventriculaires documentées symptomatiques et invalidantes;', 'tachycardies supraventriculaires documentées lorsque la nécessité d''un traitement est établie en cas de résistance ou de contre-indication aux autres thérapeutiques;', 'fibrillations ventriculaires.', 'Traitement des tachycardies supraventriculaires :', 'Ralentissement ou réduction de la fibrillation auriculaire ou du flutter auriculaire.', 'L''amiodarone peut être utilisée en présence d''une maladie coronarienne et/ou d''une altération de la fonction ventriculaire gauche (voir rubrique 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué dans les situations suivantes :', 'bradycardie sinusale et blocs sino-auriculaires non appareillés ;', 'maladie du sinus non appareillée (risque d''arrêt sinusal) ;', 'troubles conductifs auriculoventriculaires de haut degré non appareillés ;', 'hyperthyroïdie en raison de sa possible aggravation par l''amiodarone ;', 'hypersensibilité connue à l''iode ou à l’amiodarone ou à l''un des excipients;', 'les 2ème et 3ème trimestres de la grossesse ;', 'allaitement ;', 'en association avec :', 'o les médicaments torsadogènes (sauf antiparasitaires, neuroleptiques et méthadone) :', '§ les antiarythmiques de classe Ia (quinidine, hydroquinidine, disopyramide),', '§ les antiarythmiques de classe III (sotalol, dofétilide, ibutilide),']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Effets cardiaques :', 'Un ECG doit être pratiqué avant l''initiation du traitement.', 'Le ralentissement de la fréquence cardiaque peut être plus accentué chez les malades âgés.', 'Sous amiodarone, l''électrocardiogramme est modifié.', 'La survenue sous traitement d''un bloc auriculo-ventriculaire du 2ème ou 3ème degré, d''un bloc sino-auriculaire ou d''un bloc bifasciculaire doit faire arrêter le traitement.', 'Un bloc auriculo-ventriculaire du 1er degré doit faire renforcer la surveillance.', 'La survenue d''un nouveau trouble du rythme ou l''aggravation d''un trouble du rythme préexistant et traité, a été rapportée (voir rubrique 4.8).', 'Le risque d''induire des torsades de pointes sous amiodarone apparaît moindre à degré égal d''allongement de l''intervalle qu''avec d''autre anti-arythmiques.', 'Manifestations thyroïdiennes :', 'La présence d''iode dans la molécule fausse certains tests thyroïdiens (fixation de l''iode radioactif, PBI) ; néanmoins, un bilan thyroïdien est toujours possible (T3, T4, TSHus).', 'L''amiodarone peut entraîner des anomalies thyroïdiennes, particulièrement chez les patients ayant des antécédents de troubles thyroïdiens.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments antiarythmiques', 'De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l’ECG.', 'L’association d’antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L’association d’antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d’effets indésirables cardiaques.', 'Médicaments susceptibles de donner des torsades de pointes', 'Ce trouble du rythme cardiaque grave peut être provoqué par un certain nombre de médicaments, antiarythmiques ou non.', 'L''hypokaliémie (cf. médicaments hypokaliémants) est un facteur favorisant, de même que la bradycardie (cf. médicaments bradycardisants) ou un allongement préexistant de l''intervalle QT, congénital ou acquis.', 'Les médicaments concernés sont notamment des antiarythmiques de classe Ia et III, certains neuroleptiques.', 'Pour le dolasétron, l’érythromycine, la spiramycine et la vincamine, seules les formes administrées par voie intraveineuse sont concernées par cette interaction.', 'L''utilisation d''un médicament torsadogène avec un autre médicament torsadogène est contre-indiquée en règle générale.', 'Toutefois certains d’entre eux, en raison de leur caractère incontournable, font exception à la règle, en étant seulement déconseillés avec les torsadogènes.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables ont été classés par système-organe et par fréquence selon les conventions suivantes :', 'Très fréquemment (≥10%) ; fréquemment (≥1%, Affections oculaires :', 'Très fréquemment :', 'Micro-dépôts cornéens, quasiment constants chez l''adulte, restant habituellement localisés à l''aire sous-pupillaire et ne contre-indiquant pas la poursuite du traitement.', 'Exceptionnellement, ils peuvent s''accompagner de perception de halos colorés en lumière éblouissante, ou de sensation de brouillard.', 'Constitués de dépôts lipidiques complexes, les micro-dépôts cornéens sont toujours entièrement réversibles à l''arrêt du traitement.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Un bloc auriculo-ventriculaire du 1er degré doit faire renforcer la surveillance.', 'La présence d''iode dans la molécule fausse certains tests thyroïdiens (fixation de l''iode radioactif, PBI) ; néanmoins, un bilan thyroïdien est toujours possible (T3, T4, TSHus).']);
  -- sotalol (CIS 64820630, scored)
  m := pg_temp.jp_matrice_by_norm('sotalol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : BETA-BLOQUANT NON SELECTIF, code ATC : C07AA07.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention des récidives des :', 'Tachycardies ventriculaires menaçant le pronostic vital : le traitement doit être instauré en milieu hospitalier sous monitorage ;', 'Tachycardies ventriculaires documentées symptomatiques et invalidantes en l''absence d''insuffisance cardiaque non contrôlée ;', 'Tachycardies supra-ventriculaires documentées en l''absence d''insuffisance cardiaque non contrôlée lorsque la nécessité d''un traitement est établie.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament EST CONTRE-INDIQUE dans les situations suivantes :', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'Syndromes du QT long, congénitaux ou acquis ;', 'Torsades de pointes ;', 'Asthme et broncho-pneumopathies chroniques obstructives ;', 'Insuffisance cardiaque non contrôlée ;', 'Choc cardiogénique ;', 'Blocs auriculo-ventriculaires des 2ème et 3ème degrés non appareillés ;', 'Angor de Prinzmétal ;', 'Maladie du sinus (y compris bloc sino-auriculaire) non appareillée ;', 'Bradycardie (', 'Phénomène de Raynaud et troubles artériels périphériques ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'Ce médicament EST GENERALEMENT DECONSEILLE dans les situations suivantes :', 'en association avec :', 'o les antiparasitaires susceptibles de donner des torsades de pointes (chloroquine, halofantrine, lumefantrine, pentamidine)', 'o certains antagonistes des canaux calciques : diltiazem, vérapamil,', 'o le fingolimod,', 'o l’hydroxychloroquine,', 'o la méthadone,', 'o l’arsénieux,', 'o le crizotinib,', 'o le délamanid,', 'o l’association sulfaméthoxazole/triméthoprime']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['De nombreux médicaments peuvent entrainer une bradycardie.', 'De nombreux antiarythmiques sont dépresseurs de l’automatisme, de la conduction et de la contractilité cardiaques.', 'L’association d’antiarythmiques de classes différentes peut apporter un effet thérapeutique bénéfique, mais s’avère le plus souvent très délicate, nécessitant une surveillance clinique étroite et un contrôle de l’ECG.', 'L’association d’antiarythmiques donnant des torsades de pointes (amiodarone, disopyramide, quinidiniques, sotalol) est contre-indiquée.', 'L’association d’antiarythmiques de même classe est déconseillée, sauf cas exceptionnel, en raison du risque accru d’effets indésirables cardiaques.', 'La torsade de pointe, trouble du rythme cardiaque grave, peut être provoquée par un certain nombre de médicaments, antiarythmiques ou non.', 'L’hypokaliémie est un facteur favorisant, de même que la bradycardie ou un allongement préexistant de l’intervalle QT, congénital ou acquis.', 'Les médicaments à l’origine de cet effet indésirable sont notamment les antiarythmiques de classe Ia et III et certains neuroleptiques.', 'D’autres molécules n’appartenant pas à ces classes sont également en cause.', 'L’utilisation d’un médicament torsadogène avec un autre médicament torsadogène est contre-indiquée en règle générale.', 'Toutefois certains d’entre eux, en raison de leur caractère incontournable, font exception à la règle, en étant seulement déconseillés avec les autres torsadogènes.', 'Il s’agit de la méthadone, de l’hydroxychloroquine, des antiparasitaires (chloroquine, halofantrine, luméfantrine, pentamidine), de l''arsénieux, du crizotinib, du cotrimoxazole et des neuroleptiques.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquents du sotalol viennent de ses propriétés bêtabloquantes.', 'Les effets indésirables les plus graves sont ceux dus aux effets pro-arythmiques, comprenant notamment les torsades de pointes (voir rubrique 4.4).', 'Les effets indésirables sont listés par classe de système d’organes et par fréquence en utilisant la convention suivante : très fréquent (> 1/10), fréquent (> 1/100, > 1/1 000, > 1/10000,']);
  -- fosinopril (CIS 67633778, scored)
  m := pg_temp.jp_matrice_by_norm('fosinopril');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l''enzyme de conversion (IEC) non associés, code ATC : C09AA09.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle,', 'Insuffisance cardiaque congestive.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé en cas de :', 'hypersensibilité à la substance active ou à l’un des excipients, mentionnés à la rubrique 6.1 ;', 'antécédent d''angiœdème (œdème de Quincke) lié à la prise d''un inhibiteur de l''enzyme de conversion ;', '2ème et 3ème trimestres de la grossesse (voir rubriques 4.4 et 4.6) ;', 'utilisation concomitante avec un traitement par sacubitril/valsartan.', 'Le traitement par fosinopril ne doit pas être débuté moins de 36 heures après la dernière dose de sacubitril/valsartan (voir également rubriques 4.4 et 4.5).', 'Ce médicament ne doit généralement pas être utilisé dans les cas suivants :', 'associations avec les diurétiques hyperkaliémiants, les sels de potassium, l''estramustine et le lithium (voir rubrique 4.5) ;', 'sténose bilatérale de l''artère rénale ou sur rein fonctionnellement unique ;', 'hyperkaliémie ;', 'grossesse (1er trimestre).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Risque de neutropénie/ Agranulocytose sur terrain immunodéprimé', 'Des inhibiteurs de l''enzyme de conversion ont exceptionnellement entraîné une agranulocytose et/ou une dépression médullaire lorsqu''ils étaient administrés :', 'à doses élevées,', 'chez des patients insuffisants rénaux associant des maladies de système (collagénoses telles que lupus érythémateux disséminé ou sclérodermie), avec un traitement immunosuppresseur et/ou potentiellement leucopéniant.', 'Le strict respect des posologies préconisées semble constituer la meilleure prévention de la survenue de ces événements.', 'Toutefois, si un inhibiteur de l''enzyme de conversion doit être administré chez ce type de patients, le rapport bénéfice/risque sera soigneusement mesuré.', 'Hypersensibilité/angio-œdème', 'Un angio-œdème de la face, des extrémités, des lèvres, de la langue, de la glotte et/ou du larynx a été rarement signalé chez les patients traités par un inhibiteur de l''enzyme de conversion, fosinopril inclus.', 'Dans de tels cas, le fosinopril doit être arrêté immédiatement et le patient surveillé jusqu''à disparition de l''œdème.', 'Lorsque l''œdème ne concerne que la face et les lèvres, l''évolution est en général régressive sans traitement, bien que les antihistaminiques aient été utilisés pour soulager les symptômes.', 'L''angio-œdème associé à un œdème laryngé peut être fatal.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments hyperkaliémiants', 'L''association de ces médicaments majore le risque d''hyperkaliémie.', 'Pour connaître les risques et les niveaux de contrainte spécifiques aux médicaments hyperkaliémiants, il convient de se reporter aux interactions propres à chaque substance.', 'Toutefois, certaines substances, comme le triméthoprime, ne font pas l''objet d''interactions spécifiques au regard de ce risque.', 'Néanmoins, ils peuvent agir comme facteurs favorisants lorsqu''ils sont associés à d''autres médicaments déjà mentionnés dans ce chapitre.', 'Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec le racécadotril, les inhibiteurs de mTOR (par exemple sirolimus, évérolimus, temsirolimus) et la vildagliptine peut entraîner un risque accru d’angio-œdème (voir rubrique 4.4).', 'Associations contre-indiquées', '+ Médicaments augmentant le risque d’angio-œdème', 'L’utilisation concomitante d’IEC avec l’association sacubitril/valsartan est contre-indiquée en raison du risque accru d’angio-œdème (voir rubriques 4.3 et 4.4).', 'Associations déconseillées', '+ Diurétiques épargneurs de potassium, suppléments potassiques ou substituts de sel contenant du potassium']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['exceptionnellement : angio-œdème (œdème de Quincke) (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Dans de tels cas, le fosinopril doit être arrêté immédiatement et le patient surveillé jusqu''à disparition de l''œdème.']);
  -- losartan (CIS 64201553, scored)
  m := pg_temp.jp_matrice_by_norm('losartan');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique: Antagonistes de l’angiotensine II, non associés, code ATC: C09CA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension artérielle essentielle chez les adultes et les enfants et adolescents âgés de 6 à 18 ans.', 'Traitement de l''atteinte rénale chez les patients adultes diabétiques de type 2, hypertendus, avec protéinurie ≥ 0,5 g/jour, dans le cadre d''un traitement antihypertenseur (voir rubriques 4,3, 4,4, 4,5 et 5,1).', 'Le losartan ne doit pas être utilisé en traitement de relais chez les patients atteints d''insuffisance cardiaque, stabilisés par un IEC.', 'Les patients doivent avoir une fraction d''éjection ventriculaire gauche ≤ 40 % et doivent être cliniquement stabilisés et sous un traitement régulier pour l''insuffisance cardiaque chronique.', 'Réduction du risque d''accident vasculaire cérébral chez les patients adultes hypertendus présentant une hypertrophie ventriculaire gauche à l''électrocardiogramme (voir rubrique 5.1: Etude LIFE, particularités ethniques).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés aux rubriques 4.4 et 4.6.', 'Deuxième et troisième trimestres de la grossesse (voir rubriques 4.4 et 4.6).', 'Insuffisance hépatique sévère.', 'L’administration concomitante du losartan avec les médicaments contenant de l''aliskiren est contre-indiquée chez les patients atteints de diabète ou d’insuffisance rénale (DFG 2) (voir rubriques 4.5 et 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hypersensibilité', 'Angio-œdème.', 'Il convient de surveiller étroitement les patients ayant des antécédents d''angio-œdème (gonflement du visage, des lèvres, de la gorge et/ou de la langue) (voir rubrique 4.8).', 'Hypotension et déséquilibres hydro-électrolytiques', 'Il convient de traiter ces pathologies avant l''administration du losartan ou d''instaurer le traitement à une posologie plus faible (voir rubrique 4.2).', 'Ceci s''applique aussi aux enfants et aux adolescents de 6 à 18 ans.', 'Déséquilibres électrolytiques', 'Les déséquilibres électrolytiques sont fréquents et doivent être pris en compte chez les patients présentant une insuffisance rénale, qu''ils soient diabétiques ou non.', 'Insuffisance hépatique', 'Il n''y a pas d''expérience clinique avec le losartan chez les patients présentant une insuffisance hépatique sévère.', 'Le losartan ne doit donc pas être utilisé en cas d''insuffisance hépatique sévère (voir rubriques 4.2, 4.3 et 5.2).', 'Le losartan ne doit pas être utilisé chez les enfants présentant une insuffisance hépatique (voir rubrique 4.2).']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['D''autres antihypertenseurs peuvent majorer l''action hypotensive du losartan.', 'Le losartan est principalement métabolisé par le cytochrome P450 (CYP) 2C9 en son métabolite acide carboxylique actif.', 'Il a été observé dans une étude clinique que le fluconazole (un inhibiteur du CYP2C9) diminue l''exposition au métabolite actif d''environ 50 %.', 'La concentration plasmatique du métabolite actif est diminuée de 40 % en cas d''administration concomitante de losartan et de rifampicine (un inducteur des enzymes du métabolisme).', 'La pertinence clinique de cet effet est inconnue.', 'Aucune différence en termes d''exposition n''a été observée en cas d''administration concomitante avec la fluvastatine (un inhibiteur faible du CYP2C9).', 'Une administration concomitante est déconseillée.', 'Des augmentations réversibles de la lithémie avec phénomène toxique associé ont été rapportées lors de l''administration concomitante de lithium et d''IEC.', 'De très rares cas ont également été rapportés avec les antagonistes des récepteurs de l''angiotensine II.', 'La prudence s''impose en cas de co-administration de lithium et de losartan.', 'Si cette association s''avère indispensable, il est recommandé de surveiller la lithémie.', 'L''association doit être administrée avec prudence, en particulier chez le sujet âgé.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Dans ces études cliniques, les étourdissements ont été l''effet indésirable le plus fréquent.', 'La fréquence des effets indésirables répertoriés ci-dessous est définie selon la convention suivante: très fréquent (≥ 1/10); fréquent (≥ 1/100 ;']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Il convient de surveiller étroitement les patients ayant des antécédents d''angio-œdème (gonflement du visage, des lèvres, de la gorge et/ou de la langue) (voir rubrique 4.8).']);

